package com.novara.banking.servicerequest;import com.novara.banking.identity.CurrentIdentity;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/service-requests") public class ServiceRequestController{private final ServiceRequestService service;private final CurrentIdentity identities;public ServiceRequestController(ServiceRequestService s,CurrentIdentity i){service=s;identities=i;}@GetMapping ServiceRequestService.Page list(Authentication a,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="newest") String sort){return service.page(identities.from(a),Math.max(0,page),Math.min(100,Math.max(1,size)),search,sort);}@PostMapping @ResponseStatus(HttpStatus.CREATED) ServiceRequestService.View create(Authentication a,@Valid @RequestBody ServiceRequestService.Create r,@RequestHeader("Idempotency-Key") String key){return service.create(identities.from(a),r,key);}@GetMapping("/{id}") ServiceRequestService.View one(Authentication a,@PathVariable UUID id){return service.one(identities.from(a),id);}@GetMapping("/{id}/history") List<ServiceRequestService.Event> history(Authentication a,@PathVariable UUID id){return service.history(identities.from(a),id);}}
